parameters.inputSchema:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Google Queries Generator Output",
  "description": "Output schema for the Basil DeepSearch Google Queries Generator Agent",
  "type": "array",
  "items": {
    "type": "object",
    "properties": {
      "country": {
        "type": "string",
        "description": "ISO 3166-1 alpha-2 country code",
        "pattern": "^[A-Z]{2}$",
        "examples": ["US", "FR", "DE", "GB", "CN", "JP", "ES", "IT", "KR", "BR"]
      },
      "language": {
        "type": "string",
        "description": "ISO 639-1 language code",
        "pattern": "^[a-z]{2}$",
        "examples": ["en", "fr", "de", "zh", "ja", "es", "it", "ko", "pt"]
      },
      "query": {
        "type": "string",
        "description": "Complete Google search query including operators"
      },
      "priority": {
        "type": "integer",
        "description": "Query priority level (100=primary, 90=authority, 70=exploratory, 50=validation, 30=contextual)",
        "enum": [100, 90, 70, 50, 30]
      },
      "queryType": {
        "type": "string",
        "description": "Type of query based on its purpose",
        "enum": ["primary", "authority", "exploratory", "validation", "contextual"]
      },
      "rationale": {
        "type": "string",
        "description": "Brief explanation of why this query is relevant (1 sentence)"
      }
    },
    "required": ["country", "language", "query", "priority", "queryType", "rationale"],
    "additionalProperties": false
  }
}

parameters.jsCode:
const queriesSearch = [];
const inputAll = $input.all();
for (const inputKey in inputAll) {
  if (Object.prototype.hasOwnProperty.call(inputAll, inputKey)) {
    const llmOutput = inputAll[inputKey]?.json.output || [];
    queriesSearch.push(...llmOutput.map((item) => ({
      json: {
        ...item,
        strategicQuestion: $('Code_Initialize_WatchFileData').first().json.strategicQuestion,
        watchFileId: $('Code_Initialize_WatchFileData').first().json.watchFile.id,
        messageContentId: null
      }
    })));
  }
}

return queriesSearch;

